package com.aiot.log.service.impl;
import com.aiot.log.config.EnvironmentProperties; import com.aiot.log.dto.EnvironmentSpaceRequest; import com.aiot.log.entity.Device; import com.aiot.log.entity.EnvironmentSpace; import com.aiot.log.exception.BusinessException; import com.aiot.log.exception.ErrorCode; import com.aiot.log.mapper.DeviceMapper; import com.aiot.log.mapper.EnvironmentSpaceMapper; import com.aiot.log.service.EnvironmentSpaceService; import com.aiot.log.vo.EnvironmentSpaceVO; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import org.springframework.stereotype.Service; import java.util.List;
@Service public class EnvironmentSpaceServiceImpl implements EnvironmentSpaceService {
 private final EnvironmentSpaceMapper mapper; private final DeviceMapper devices; private final EnvironmentProperties properties;
 public EnvironmentSpaceServiceImpl(EnvironmentSpaceMapper m, DeviceMapper d, EnvironmentProperties p){mapper=m;devices=d;properties=p;}
 public List<EnvironmentSpaceVO> list(){return mapper.selectList(new LambdaQueryWrapper<EnvironmentSpace>().orderByDesc(EnvironmentSpace::getCreatedAt)).stream().map(this::toVO).toList();}
 public EnvironmentSpaceVO create(EnvironmentSpaceRequest r){EnvironmentSpace s=new EnvironmentSpace(); fill(s,r); mapper.insert(s); return toVO(s);}
 public EnvironmentSpaceVO update(Long id, EnvironmentSpaceRequest r){EnvironmentSpace s=get(id); fill(s,r); mapper.updateById(s); return toVO(s);}
 public void delete(Long id){mapper.deleteById(get(id).getId());}
 private EnvironmentSpace get(Long id){EnvironmentSpace s=mapper.selectById(id); if(s==null) throw new BusinessException(ErrorCode.ENVIRONMENT_SPACE_NOT_FOUND); return s;}
 private void fill(EnvironmentSpace s, EnvironmentSpaceRequest r){if((r.getLatitude()==null)!=(r.getLongitude()==null)) throw new BusinessException(ErrorCode.REQUEST_VALIDATION_FAILED,"经纬度必须同时填写"); if(r.getPrimarySpeakerDeviceId()!=null&&devices.selectById(r.getPrimarySpeakerDeviceId())==null) throw new BusinessException(ErrorCode.DEVICE_NOT_FOUND); if(r.getIndoorSensorDeviceId()!=null&&devices.selectById(r.getIndoorSensorDeviceId())==null) throw new BusinessException(ErrorCode.DEVICE_NOT_FOUND); s.setName(r.getName());s.setAddress(r.getAddress());s.setLatitude(r.getLatitude());s.setLongitude(r.getLongitude());s.setPrimarySpeakerDeviceId(r.getPrimarySpeakerDeviceId());s.setIndoorSensorDeviceId(r.getIndoorSensorDeviceId());s.setEnabled(r.getEnabled()==null?true:r.getEnabled());}
 private EnvironmentSpaceVO toVO(EnvironmentSpace s){EnvironmentSpaceVO v=new EnvironmentSpaceVO();v.id=s.getId();v.name=s.getName();v.address=s.getAddress();v.latitude=s.getLatitude();v.longitude=s.getLongitude();v.primarySpeakerDeviceId=s.getPrimarySpeakerDeviceId();v.indoorSensorDeviceId=s.getIndoorSensorDeviceId();v.enabled=s.getEnabled();v.outdoorSourceConfigured=properties.isConfigured();v.createdAt=s.getCreatedAt();v.updatedAt=s.getUpdatedAt();if(s.getPrimarySpeakerDeviceId()!=null){Device d=devices.selectById(s.getPrimarySpeakerDeviceId());if(d!=null)v.primarySpeakerName=d.getName();}if(s.getIndoorSensorDeviceId()!=null){Device d=devices.selectById(s.getIndoorSensorDeviceId());if(d!=null)v.indoorSensorName=d.getName();}return v;}
}
